Here's your expense tracker. Add an item, pick a category, and the total and category bars update as you go. Set a monthly budget to see what's left. It tries to save in your browser, but if saving is blocked here, entries last only while this page stays open.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:14px;background:#fafafa;color:#222}
h2{margin:0 0 10px;font-size:18px}
.card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:12px;margin-bottom:12px}
.row{display:flex;gap:6px;flex-wrap:wrap}
input,select,button{font:inherit;padding:7px 9px;border:1px solid #bbb;border-radius:7px}
input{flex:1;min-width:90px}
button{background:#2b6cb0;color:#fff;border-color:#2b6cb0;cursor:pointer}
button.x{background:none;color:#c53030;border:none;padding:2px 6px}
.big{font-size:24px;font-weight:600}
.muted{color:#666;font-size:13px}
.bar{height:8px;background:#e2e8f0;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar>div{height:100%;background:#2b6cb0}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.over{color:#c53030}
</style></head><body>
<div class="card">
<h2>Monthly expenses</h2>
<div class="big" id="total">₹0</div>
<div class="muted" id="left">Set a budget to see what is left</div>
<div class="row" style="margin-top:8px">
<input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
</div>
</div>
<div class="card">
<div class="row">
<input id="name" placeholder="What did you spend on?">
<input id="amt" type="number" min="0" placeholder="Amount (₹)">
<select id="cat">
<option>Food</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
</select>
<button type="button" id="add">Add</button>
</div>
</div>
<div class="card"><h2>By category</h2><div id="cats" class="muted">Nothing yet</div></div>
<div class="card"><h2>Entries</h2><div id="list" class="muted">Nothing yet</div></div>
<script>
var items=[],budget=0,KEY="foo_expenses_v1";
function fmt(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
try{var s=JSON.parse(localStorage.getItem(KEY)||"null");if(s){items=s.items||[];budget=s.budget||0}}catch(e){}
function save(){try{localStorage.setItem(KEY,JSON.stringify({items:items,budget:budget}))}catch(e){}}
function esc(t){var d=document.createElement("div");d.textContent=t;return d.innerHTML}
function render(){
var tot=0,by={};
items.forEach(function(i){tot+=i.amt;by[i.cat]=(by[i.cat]||0)+i.amt});
document.getElementById("total").textContent=fmt(tot);
var l=document.getElementById("left");
if(budget>0){var r=budget-tot;l.className=r<0?"muted over":"muted";l.textContent=r<0?"Over budget by "+fmt(-r):fmt(r)+" left of "+fmt(budget)}
else{l.className="muted";l.textContent="Set a budget to see what is left"}
var c=document.getElementById("cats");
var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a]});
c.innerHTML=keys.length?keys.map(function(k){var p=tot?by[k]/tot*100:0;
return "<div><div class='item' style='border:none;padding:0'><span>"+esc(k)+"</span><span>"+fmt(by[k])+"</span></div><div class='bar'><div style='width:"+p.toFixed(0)+"%'></div></div></div>"}).join(""):"Nothing yet";
var li=document.getElementById("list");
li.innerHTML=items.length?items.map(function(i,n){
return "<div class='item'><span>"+esc(i.name)+" <span class='muted'>· "+esc(i.cat)+"</span></span><span>"+fmt(i.amt)+" <button class='x' data-n='"+n+"'>✕</button></span></div>"}).reverse().join(""):"Nothing yet";
}
document.getElementById("add").onclick=function(){
var n=document.getElementById("name").value.trim(),a=parseFloat(document.getElementById("amt").value);
if(!n||!(a>0))return;
items.push({name:n,amt:a,cat:document.getElementById("cat").value});
document.getElementById("name").value="";document.getElementById("amt").value="";
save();render();
};
document.getElementById("list").onclick=function(e){
var n=e.target.getAttribute("data-n");
if(n!==null){items.splice(+n,1);save();render()}
};
var b=document.getElementById("budget");
if(budget)b.value=budget;
b.oninput=function(){budget=parseFloat(b.value)||0;save();render()};
render();
</script>
</body></html>
```

